fn decode_shift(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            // Convert 'a'..'z' to 0..25
            let alpha_index = c as u8 - b'a';
            // Shift left by 5 with wrap-around in 0..26
            let decoded_index = (alpha_index + 26 - 5) % 26;
            // Convert back to 'a'..'z'
            (b'a' + decoded_index) as char
        })
        .collect()
}

fn main() {
    let input = vec!['a', 'b', 'f', 'z', 'm'];
    let output = decode_shift(input);
    assert_eq!(output, vec!['v', 'w', 'a', 'u', 'h']);
    println!("{:?}", output); // prints ['v', 'w', 'a', 'u', 'h']
}